var vert=`
attribute vec3 aPosition;
attribute vec3 aNormal;
attribute vec2 aTexCoord;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;
uniform mat3 uNormalMatrix;

varying vec3 vVertexNormal;
varying highp vec2 vVertTexCoord;

void main(void) {
  vec4 positionVec4 = vec4(aPosition, 1.0);
  gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
  vVertexNormal = normalize(vec3( uNormalMatrix * aNormal ));
  vVertTexCoord = aTexCoord;
}
`;
var frag=`#ifdef GL_ES
precision highp float;
precision highp int;
#endif
uniform float time;
uniform vec4 col;
uniform vec2 center;   
uniform vec2 resolution;
uniform sampler2D tex;

void main( void ) {
	vec4 me=vec4(0);
	vec2 position =vec2( gl_FragCoord.xy / resolution.xy);
vec2 pos=vec2(position.x,1.0-position.y);
  float rnd1= fract(sin(dot(position + time * 0.001, vec2(14.9898,78.233))) * 43758.5453);
  float rnd2 =fract(sin(dot(position + time * 0.0013, vec2(14.8898,78.233))) * 43758.5453); 
	float rnd3 =fract(sin(dot(position + time * 0.0015, vec2(14.8898,78.233))) * 43758.5453); 
  vec2 link=(center-position);
  float dst=100.0*pow(length(link),.3);
  link/=dst;
dst/=250.0;
vec2 mov=vec2(link.y,-link.x)*dst+2.0*link+vec2(.5-rnd1,.5-rnd2)/(200.0);
me = texture2D(tex, vec2(position.x+mov.x,1.0-position.y-mov.y)); 
float r=mod(me.x+(0.5-rnd1)*dst,1.0);
float g=mod(me.y+(0.5-rnd2)*dst,1.0);
float b=mod(me.z+(0.5-rnd3)*dst,1.0);
  me=vec4(r,g,b,1.0);
  gl_FragColor = mix(me,col,.01*length(position-center)); 
}
	`;

